import { Button as HeroButton, buttonVariants, type ButtonProps } from "@heroui/react";
import { tv, type VariantProps } from "tailwind-variants";

/**
 * Jalat Button — extended variant of HeroUI v3's Button.
 * Follows the official `extend: buttonVariants` pattern: variant/size classes are
 * generated by tailwind-variants and applied via className, so we never pass
 * `variant` down raw. Feature code imports this, never `@heroui/react` directly.
 */
const jalatButton = tv({
  extend: buttonVariants,
  base: "font-semibold tracking-tight",
  compoundVariants: [
    {
      // Brand primary = Figma light sky blue (#4FB5DB). HeroUI's "primary" is a
      // style variant coloured from its dark `default` token, so recolour here.
      variant: "primary",
      class:
        "!bg-primary-lightskyblue !border-primary-lightskyblue !text-white hover:!bg-primary-lightskyblue/90 data-[hovered=true]:!bg-primary-lightskyblue/90 data-[pressed=true]:!bg-primary-lightskyblue/80",
    },
    {
      // Solid danger button for destructive confirm dialogs.
      variant: "danger",
      class:
        "!bg-danger !border-danger !text-white hover:!bg-danger/90 data-[hovered=true]:!bg-danger/90 data-[pressed=true]:!bg-danger/80",
    },
  ],
});

type JalatButtonVariants = VariantProps<typeof jalatButton>;

export type UIButtonProps = Omit<ButtonProps, "className" | "variant" | "size"> &
  JalatButtonVariants & { className?: string };

export function Button({ className, variant, size, ...props }: UIButtonProps) {
  return <HeroButton className={jalatButton({ className, variant, size })} {...props} />;
}
